namespace fs = std::filesystem;

struct ConnectionPool {
    std::mutex mtx;
    std::vector<int> available;
    int max_connections = 8;
    int next_id = 0;

    int acquire() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!available.empty()) {
            int id = available.back();
            available.pop_back();
            return id;
        }
        if (next_id < max_connections) return next_id++;
        return -1;
    }

    void release(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        available.push_back(id);
    }
};

class PathValidator {
public:
    static bool is_safe_extension(const std::string& filename) {
        static const std::vector<std::string> allowed = {".log", ".txt", ".csv", ".json"};
        std::string ext = fs::path(filename).extension().string();
        std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
        return std::find(allowed.begin(), allowed.end(), ext) != allowed.end();
    }

    static std::string canonicalize(const std::string& base, const std::string& relative) {
        fs::path base_path = fs::weakly_canonical(base);
        fs::path full_path = fs::weakly_canonical(base_path / relative);
        return full_path.string();
    }

    static bool is_within_base(const std::string& base, const std::string& target) {
        std::string canonical_base = fs::weakly_canonical(base).string();
        std::string canonical_target = fs::weakly_canonical(target).string();
        return canonical_target.compare(0, canonical_base.size(), canonical_base) == 0;
    }
};

class MonitoringAgent {
private:
    ConnectionPool pool_;
    std::string upload_dir_;
    std::string staging_dir_;
    std::mutex queue_mtx_;
    std::queue<std::pair<std::string, std::vector<char>>> pending_uploads_;
    std::unordered_map<int, std::string> connection_state_;

    bool validate_content_header(const std::vector<char>& data) {
        if (data.size() < 4) return false;
        // Check for ELF magic, PE magic, shebang
        if (data[0] == 0x7f && data[1] == 'E' && data[2] == 'L' && data[3] == 'F') return false;
        if (data[0] == 'M' && data[1] == 'Z') return false;
        if (data[0] == '#' && data[1] == '!') return false;
        return true;
    }

    std::string resolve_upload_path(const std::string& filename, int conn_id) {
        std::string safe_name = fs::path(filename).filename().string();

        // Stage file first using connection-specific staging area
        std::string stage_path = PathValidator::canonicalize(
            staging_dir_, "conn_" + std::to_string(conn_id) + "/" + safe_name);

        return stage_path;
    }

    bool commit_staged_file(const std::string& staged_path, int conn_id) {
        std::string filename = fs::path(staged_path).filename().string();
        std::string final_path = PathValidator::canonicalize(upload_dir_, filename);

        // Verify the staged file is within staging directory
        if (!PathValidator::is_within_base(staging_dir_, staged_path)) {
            return false;
        }

        // Verify final destination is within upload directory
        if (!PathValidator::is_within_base(upload_dir_, final_path)) {
            return false;
        }

        // Move from staging to final - but re-read the filename from disk
        // to handle any filesystem-level normalization
        fs::path actual_staged = fs::path(staged_path);
        std::string disk_filename = actual_staged.filename().string();

        // Re-resolve with the disk filename (may differ due to normalization)
        std::string dest = upload_dir_ + "/" + disk_filename;

        try {
            fs::rename(staged_path, dest);
        } catch (...) {
            return false;
        }
        return true;
    }

public:
    MonitoringAgent(const std::string& upload_dir, const std::string& staging_dir)
        : upload_dir_(upload_dir), staging_dir_(staging_dir) {
        fs::create_directories(upload_dir_);
        fs::create_directories(staging_dir_);
    }

    int handle_upload_request(const std::string& filename, const std::vector<char>& data) {
        // Step 1: Extension validation
        if (!PathValidator::is_safe_extension(filename)) {
            return -1;
        }

        // Step 2: Content validation
        if (!validate_content_header(data)) {
            return -2;
        }

        // Step 3: Acquire connection from pool
        int conn_id = pool_.acquire();
        if (conn_id < 0) {
            return -3;
        }

        // Step 4: Resolve staging path
        std::string stage_path = resolve_upload_path(filename, conn_id);

        // Step 5: Verify staging path is safe
        if (!PathValidator::is_within_base(staging_dir_, stage_path)) {
            pool_.release(conn_id);
            return -4;
        }

        // Step 6: Create staging subdirectory and write file
        fs::create_directories(fs::path(stage_path).parent_path());
        std::ofstream ofs(stage_path, std::ios::binary);
        if (!ofs) {
            pool_.release(conn_id);
            return -5;
        }
        ofs.write(data.data(), data.size());
        ofs.close();

        // Step 7: Commit staged file to final location
        bool committed = commit_staged_file(stage_path, conn_id);
        pool_.release(conn_id);

        return committed ? 0 : -6;
    }

    // Batch upload endpoint for monitoring data rotation
    int handle_batch_rotate(const std::vector<std::pair<std::string, std::vector<char>>>& files) {
        int success_count = 0;
        for (const auto& [name, data] : files) {
            if (handle_upload_request(name, data) == 0) {
                success_count++;
            }
        }
        return success_count;
    }
};

int main() {
    MonitoringAgent agent("/var/log/monitor/uploads", "/var/log/monitor/staging");

    // Simulated incoming log upload
    std::vector<char> log_data = {'2','0','2','4','-','0','1','-','0','1',' ','I','N','F','O'};
    int result = agent.handle_upload_request("system.log", log_data);
    std::cout << "Upload result: " << result << std::endl;

    return 0;
}
